package owl.nh;
import java.awt.*;import java.net.*;import java.nio.file.*;import java.lang.reflect.*;import javax.swing.*;
/** Loads only the independently built Gauntlet module and profile store. */
final class GauntletFeature implements AutoCloseable {
 private final CombatRuntime runtime;private URLClassLoader loader;private Object module;
 GauntletFeature(CombatRuntime runtime){this.runtime=runtime;}
 Window window(JFrame owner){try{if(module==null){Path root=CombatRuntime.projectRoot().toPath().toAbsolutePath().normalize();Path marker=root.resolve("release-gauntlet.txt");String selected=Files.isRegularFile(marker)?Files.readString(marker).trim():"TurboGauntlet.jar";Path jar=root.resolve(selected).normalize();if(!jar.startsWith(root)||!Files.isRegularFile(jar))throw new IllegalStateException("TurboGauntlet.jar is missing. Rebuild or update the Gauntlet module.");loader=new URLClassLoader(new URL[]{jar.toUri().toURL()},getClass().getClassLoader());try{Class<?> type=Class.forName("turbo.gauntlet.GauntletModule",true,loader);module=type.getConstructor(net.runelite.api.Client.class,net.runelite.client.callback.ClientThread.class,net.runelite.client.eventbus.EventBus.class,Frame.class,Path.class,Runnable.class,RaidInputBridge.class).newInstance(runtime.client,runtime.thread,runtime.busForModules(),owner,root.resolve("profiles/gauntlet"),(Runnable)()->runtime.stop("Starting Gauntlet module"),runtime.raidInputBridge);}catch(Throwable error){loader.close();loader=null;throw error;}}return (Window)module.getClass().getMethod("window").invoke(module);}catch(Throwable error){while(error instanceof InvocationTargetException&&error.getCause()!=null)error=error.getCause();throw new IllegalStateException("Gauntlet window could not open: "+error.getMessage(),error);}}
 void stop(String reason){if(module!=null)try{module.getClass().getMethod("stop",String.class).invoke(module,reason);}catch(ReflectiveOperationException e){throw new IllegalStateException("Cannot stop Gauntlet",e);}}
 public void close(){try{if(module!=null)module.getClass().getMethod("close").invoke(module);}catch(ReflectiveOperationException ignored){}finally{module=null;if(loader!=null)try{loader.close();}catch(java.io.IOException ignored){}loader=null;}}
}
